/**
 * map.js -- Slovingo adventure map (homepage).
 *
 * Responsibilities, kept apart on purpose:
 *   - DATA     map.json (generated by src/map_generator.py): which steps
 *              exist, their order, coordinates and sheets.
 *   - PROGRESS read-only, from the existing stores (progress.js):
 *              exercise scores and visited sheets. The map has no
 *              progress store of its own.
 *   - STATE    deriveMapState(): pure function, progress -> step states.
 *   - RENDER   DOM, SVG path, fog, fox.
 *
 * The map never decides how an exercise is scored or what counts as a
 * sheet: it only reads averageScore() and the visited sheets, and
 * compares the average to the validation threshold.
 *
 * Locking is visual only: every node is a real button/link target and
 * the fog never intercepts clicks.
 */

/*
 * Everything below lives in a function scope, NOT the page's global one:
 * the front-end is a set of classic scripts sharing one global scope,
 * and a helper named like another script's (exercises.js already has
 * its own `el`) silently overwrites it. Only renderMap is exported.
 */
(function () {
"use strict";

/** Fallbacks if map.json carries no `config` (see map_generator.py). */
const MAP_DEFAULTS = {
    validationThreshold: 85,
};

/**
 * Static scenery, placeholder until real artwork exists. The path runs
 * from the top (meadow) down to the castle, so the Tatras stand behind
 * the castle at the bottom.
 */
const MAP_DECORATIONS = [
    { icon: "🌲", x: 6, y: 24, size: 1.6 },
    { icon: "🌲", x: 10, y: 33, size: 1.4 },
    { icon: "🌲", x: 94, y: 48, size: 1.6 },
    { icon: "🌲", x: 90, y: 57, size: 1.4 },
    { icon: "🌲", x: 6, y: 62, size: 1.6 },
    { icon: "🌲", x: 11, y: 71, size: 1.4 },
    { icon: "🏞️", x: 12, y: 84, size: 1.6 },
    { icon: "🏔️", x: 13, y: 95, size: 2.8 },
    { icon: "🏔️", x: 88, y: 94, size: 3 },
    { icon: "🏔️", x: 31, y: 97, size: 2 },
    { icon: "🏔️", x: 69, y: 97, size: 2.2 },
];

const SVG_NS = "http://www.w3.org/2000/svg";

/** @type {object|null} Parsed map.json, fetched once. */
let MAP_DATA = null;

// ============================================================================
// 1. Data
// ============================================================================

/** @returns {Promise<object|null>} map.json, or null if the course has none. */
async function loadMapData() {
    if (MAP_DATA) {
        return MAP_DATA;
    }
    try {
        const response = await fetch("map.json");
        if (!response.ok) {
            return null;
        }
        MAP_DATA = await response.json();
        return MAP_DATA;
    } catch (err) {
        return null;
    }
}

// ============================================================================
// 2. State (pure: progress in, step states out)
// ============================================================================

/**
 * Score of a step, from the existing exercise progress. Same rule as
 * the group badge on the sheet list: only sheets that have exercises
 * count, and an unpracticed one counts as 0.
 *
 * @param {{sheets: string[]}} step
 * @returns {number|null} Average percent, or null if never practiced.
 */
function stepScore(step) {
    const scorable = step.sheets.filter((id) => EXERCISES && EXERCISES.sheets[id]);
    const score = averageScore(scorable);
    return score ? score.avg : null;
}

/**
 * Derive every step's state from the stored progress.
 *
 * Rules (see the map specs):
 *  - series: validated when its average >= threshold;
 *  - intro / survival: validated once every sheet has been opened;
 *  - a step is discovered when its index <= highest validated index + 1
 *    (so Serie 5 stays clickable, just in the fog);
 *  - the current step is the first one not validated.
 *
 * @param {object[]} steps map.json steps, in path order.
 * @param {object} config map.json config.
 * @returns {{steps: object[], currentIndex: number, lastValidatedIndex: number}}
 */
function deriveMapState(steps, config) {
    return deriveFromFlags(steps, stepFlags(steps, config));
}

/**
 * Per-step facts read from the stored progress: score, whether the
 * step is validated, whether the learner started it.
 * @returns {{score: number|null, validated: boolean, started: boolean}[]}
 */
function stepFlags(steps, config) {
    const threshold = (config && config.validationThreshold) || MAP_DEFAULTS.validationThreshold;
    const visited = getVisitedSheets();

    const flags = steps.map((step) => {
        const visitedCount = step.sheets.filter((id) => visited[id]).length;
        const score = step.type === "final" ? null : stepScore(step);
        let validated = false;
        if (step.type === "series") {
            validated = score !== null && score >= threshold;
        } else if (step.type === "intro" || step.type === "survival") {
            validated = step.sheets.length > 0 && visitedCount === step.sheets.length;
        }
        return { score, validated, started: visitedCount > 0 || score !== null };
    });
    // The final step (the credits series) is reached, shown as "validated",
    // once every step before it is. A castle without any sheet is only
    // scenery: it is never reached.
    steps.forEach((step, index) => {
        if (step.type === "final" && step.sheets.length > 0) {
            flags[index].validated = flags.every((flag, other) => other === index || flag.validated);
        }
    });
    return flags;
}

/**
 * Pure part of the derivation: validated flags in, discovered/current
 * out. Kept separate so the map can also be drawn "as it was" before
 * a validation, to animate the change.
 */
function deriveFromFlags(steps, flags) {
    const states = flags.map((flag) => ({ ...flag }));

    let lastValidatedIndex = -1;
    states.forEach((state, index) => {
        if (state.validated) {
            lastValidatedIndex = index;
        }
    });

    let currentIndex = states.findIndex((state, index) => !state.validated && steps[index].type !== "final");
    if (currentIndex === -1) {
        currentIndex = steps.length - 1;
    }

    states.forEach((state, index) => {
        state.discovered = index <= lastValidatedIndex + 1;
        state.current = index === currentIndex;
    });

    return { steps: states, currentIndex, lastValidatedIndex };
}

/**
 * Index of the step the fox stands at: the step holding the last
 * sheet the learner opened, whatever its validation state.
 * @returns {number} -1 if nothing was opened yet.
 */
function foxStepIndex(steps) {
    const lastId = getLastSheetId();
    if (!lastId) {
        return -1;
    }
    return steps.findIndex((step) => step.sheets.includes(lastId));
}

/** @returns {string} CSS state class for a node (one state at a time). */
function nodeStateClass(state) {
    if (state.validated) return "is-validated";
    if (state.current) return "is-current";
    if (state.started && state.discovered) return "is-in-progress";
    if (state.discovered) return "is-discovered";
    return "is-future";
}

/** @returns {string} Screen-reader description of a node's state. */
function nodeStateText(state) {
    if (state.validated) return uiLabel("map_completed", "completed");
    if (state.current) return uiLabel("map_current", "current step");
    if (state.started && state.discovered) return uiLabel("map_in_progress", "in progress");
    if (state.discovered) return uiLabel("map_discovered", "discovered");
    return uiLabel("map_not_discovered", "not discovered yet");
}

// ============================================================================
// 2b. What the map has already shown (to animate only what is new)
// ============================================================================

/**
 * The map is always derived from the progress; this only remembers
 * which validated steps the learner has already SEEN on the map, so
 * that the reveal animation plays once, and never replays after a
 * refresh or a long absence. It is display memory, not progress.
 */
function seenKey() {
    const prefix = (LANG && LANG.site && LANG.site.storage_prefix) || "slovingo";
    return `${prefix}-map-seen`;
}

/** @returns {string[]|null} Validated step ids last shown, null if never shown. */
function loadSeenValidated() {
    try {
        const data = JSON.parse(localStorage.getItem(seenKey()));
        return data && Array.isArray(data.validated) ? data.validated : null;
    } catch (err) {
        return null;
    }
}

function saveSeenValidated(steps, state) {
    try {
        const validated = steps.filter((step, index) => state.steps[index].validated).map((step) => step.id);
        localStorage.setItem(seenKey(), JSON.stringify({ validated }));
    } catch (err) {
        // ignore
    }
}

/**
 * Indices of the steps validated since the map was last shown.
 * Empty on the very first display: someone who already has progress
 * must not watch their whole history replay.
 */
function newlyValidatedIndexes(steps, state) {
    const seen = loadSeenValidated();
    if (seen === null) {
        return [];
    }
    return steps.map((step, index) => index).filter((index) => state.steps[index].validated && !seen.includes(steps[index].id));
}

function prefersReducedMotion() {
    return typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
}

// ============================================================================
// 3. Geometry
// ============================================================================

/**
 * SVG path commands for the Catmull-Rom spline through `points`,
 * as one cubic Bezier per segment.
 * @param {number[][]} points [x, y] in SVG units.
 * @returns {string[]} segment i is "M p_i C c1 c2 p_i+1".
 */
function splineSegments(points) {
    const at = (i) => points[Math.max(0, Math.min(points.length - 1, i))];
    const segments = [];
    for (let i = 0; i < points.length - 1; i++) {
        const p0 = at(i - 1);
        const p1 = at(i);
        const p2 = at(i + 1);
        const p3 = at(i + 2);
        const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
        const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
        segments.push(`M ${p1[0]},${p1[1]} C ${c1[0]},${c1[1]} ${c2[0]},${c2[1]} ${p2[0]},${p2[1]}`);
    }
    return segments;
}

// ============================================================================
// 4. Rendering
// ============================================================================

function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
}

function svgPath(className, d) {
    const path = document.createElementNS(SVG_NS, "path");
    path.setAttribute("class", className);
    path.setAttribute("d", d);
    return path;
}

/**
 * Render the map at the top of `container`. The wrapper is appended
 * synchronously (so it stays above the sheet list the caller appends
 * next); it is filled once map.json is available.
 *
 * @param {HTMLElement} container The home view's content element.
 * @returns {Promise<boolean>} true if a map was drawn.
 */
async function renderMap(container) {
    const wrap = el("div", "map-wrap");
    wrap.hidden = true;
    container.appendChild(wrap);

    const data = await loadMapData();
    if (!data || !wrap.isConnected) {
        return false;
    }
    const steps = data.steps || [];
    if (steps.filter((step) => step.type !== "final").length === 0) {
        return false;
    }

    const cheating = cheatRequested();
    const flags = stepFlags(steps, data.config);
    if (cheating) {
        // Test mode (?cheat=fireworks): pretend the whole course is done.
        // Nothing is stored: the real progress is left untouched.
        flags.forEach((flag) => { flag.validated = true; });
    }
    const state = deriveFromFlags(steps, flags);
    const newly = cheating
        ? [steps.length - 1]
        : newlyValidatedIndexes(steps, state);
    // Saved BEFORE any animation: the progress is already stored, and an
    // interrupted animation must never replay.
    if (!cheating) {
        saveSeenValidated(steps, state);
    }
    const animate = newly.length > 0 && !prefersReducedMotion();
    // When animating, draw the map as it was, then switch to the new state.
    const shown = animate
        ? deriveFromFlags(steps, flags.map((flag, index) => ({ ...flag, validated: flag.validated && !newly.includes(index) })))
        : state;
    const section = buildScene(steps, shown, data.config || {});
    wrap.appendChild(section);
    const bubble = buildBubble(section);
    // The fox walks to the clicked step, then its bubble opens. Nothing
    // waits on the fox but the bubble: the links inside it are what open
    // a sheet, so access stays free.
    section.addEventListener("click", async (event) => {
        if (event.target.closest(".map-bubble")) {
            return;
        }
        const node = event.target.closest(".map-node");
        if (!node) {
            bubble.close(); // a click anywhere else on the map
            return;
        }
        const index = Number(node.dataset.index);
        if (bubble.index === index) {
            bubble.close(true); // second click on the same step
            return;
        }
        bubble.close();
        if (await walkFox(section, steps, index)) {
            bubble.open(index, node);
        }
    });
    section.addEventListener("keydown", (event) => {
        if (event.key === "Escape" && bubble.isOpen) {
            bubble.close(true);
        }
    });
    // The bubble is placed in pixels: a refit (rotation) would strand it.
    section.addEventListener("map:refit", () => bubble.close());
    const nav = buildResourcesNav(data.resources || []);
    if (nav) {
        wrap.appendChild(nav);
    }
    wrap.hidden = false;

    fitMapToScreen(section);
    placeFox(section, steps);

    if (newly.length) {
        celebrate(section, steps, state, newly, animate);
    }
    return true;
}

// Room left under the map so it is not glued to the screen's bottom edge.
const MAP_BOTTOM_GAP = 16;
const MAP_MIN_HEIGHT = 380;
const MAP_MAX_HEIGHT = 760;
// Vertical room each step needs so that neighbouring labels never touch.
// The path only spans ~67% of the map's height (top 9% .. 76%, the castle
// below), hence the division in neededHeight().
const MAP_STEP_GAP = 42;
const MAP_PATH_SHARE = 0.67;

/**
 * Height needed by a course with many series: the screen-fitting height
 * is only a maximum for ordinary courses; a long course gets a taller map
 * (the page scrolls) instead of squeezing its steps together.
 */
function neededHeight(stepCount) {
    return Math.round((MAP_STEP_GAP * Math.max(stepCount - 2, 1)) / MAP_PATH_SHARE);
}

let fitCleanup = null;

/**
 * Size the map so that it fits the screen: from where it starts down to
 * the bottom of the viewport. The space above it (title band, toolbar)
 * is measured, not guessed, so it keeps working if that header changes.
 * Re-fitted on a width change (rotation) or a big height change, but
 * not on the small ones a mobile browser makes when its address bar
 * slides away -- the map would jump under the learner's thumb.
 */
function fitMapToScreen(section) {
    if (fitCleanup) {
        fitCleanup();
        fitCleanup = null;
    }
    const fit = () => {
        const top = section.getBoundingClientRect().top + window.scrollY;
        const room = window.innerHeight - top - MAP_BOTTOM_GAP;
        const fitted = Math.min(MAP_MAX_HEIGHT, Math.max(MAP_MIN_HEIGHT, room));
        const height = Math.max(fitted, neededHeight(Number(section.dataset.steps) || 0));
        section.style.setProperty("--map-height", `${Math.round(height)}px`);
    };
    fit();

    let lastWidth = window.innerWidth;
    let lastHeight = window.innerHeight;
    const onResize = () => {
        if (!section.isConnected) {
            fitCleanup();
            fitCleanup = null;
            return;
        }
        if (window.innerWidth !== lastWidth || Math.abs(window.innerHeight - lastHeight) > 120) {
            lastWidth = window.innerWidth;
            lastHeight = window.innerHeight;
            fit();
            section.dispatchEvent(new Event("map:refit"));
        }
    };
    window.addEventListener("resize", onResize);
    fitCleanup = () => window.removeEventListener("resize", onResize);
}

/**
 * The "magic moment" after a validation, 3.5 s at most, never blocking
 * (the toast ignores pointer events, every node stays clickable):
 *   0 s     toast: series completed + score
 *   0.5 s   the fox hops
 *   1.1 s   fog lifts, path lights up, next step becomes current
 *   3.5 s   toast removed
 * With reduced motion the new state is already drawn and only the
 * (static) message is shown.
 */
function celebrate(section, steps, state, newly, animate) {
    const index = newly[newly.length - 1];
    const step = steps[index];
    if (step.type === "final") {
        finale(section, steps, state, animate);
        return;
    }
    const score = state.steps[index].score;
    const toast = el("div", "map-toast");
    toast.setAttribute("role", "status");
    toast.textContent = step.type === "series"
        ? `🎉 ${uiLabel("map_series_done", "Series completed!")} ${step.title}${score !== null ? ` · ${score}%` : ""}`
        : `🎉 ${uiLabel("map_step_done", "Step completed!")} ${step.title}`;
    section.appendChild(toast);

    const alive = () => section.isConnected;
    if (!animate) {
        setTimeout(() => toast.remove(), 4000);
        return;
    }

    const fox = section.querySelector("#map-fox");
    setTimeout(() => alive() && fox.classList.add("is-celebrating"), 500);
    setTimeout(() => {
        if (alive()) {
            fox.classList.remove("is-celebrating");
            applyState(section, steps, state);
        }
    }, 1100);
    setTimeout(() => toast.remove(), 3500);
}

// ============================================================================
// 4b. The finale: the credits series is reached
// ============================================================================

/**
 * Reaching the final step (the credits series): the map scrolls to it if
 * it is out of sight, the step lights up, and fireworks go off over the
 * map for about five seconds. Nothing is blocked: the fireworks canvas
 * ignores pointer events. With reduced motion there is no fireworks and
 * no scrolling: the step is simply drawn reached, with the message.
 */
function finale(section, steps, state, animate) {
    const finalIndex = steps.length - 1;
    const toast = el("div", "map-toast map-toast--finale");
    toast.setAttribute("role", "status");
    toast.textContent = `🎆 ${uiLabel("map_final_reached", "Bravo! You finished the whole journey!")}`;
    section.appendChild(toast);

    if (!animate) {
        applyState(section, steps, state);
        setTimeout(() => toast.remove(), 6000);
        return;
    }
    const node = section.querySelector(`.map-node[data-index="${finalIndex}"]`);
    if (node) {
        const rect = node.getBoundingClientRect();
        if (rect.top < 0 || rect.bottom > window.innerHeight) {
            node.scrollIntoView({ behavior: "smooth", block: "center" });
        }
    }
    setTimeout(() => {
        if (!section.isConnected) {
            return;
        }
        applyState(section, steps, state);
        launchFireworks(node);
    }, 700);
    setTimeout(() => toast.remove(), 6000);
}

/**
 * Fireworks on a full-screen canvas laid over the page (pointer-events:
 * none). Rockets rise from the bottom and burst around `anchor` (the
 * castle) in coloured particles that fall under gravity and fade. Ends
 * by itself after ~5 s, or at once if the map is left.
 * @param {HTMLElement|null} anchor Element the shells burst around.
 */
function launchFireworks(anchor) {
    if (document.querySelector(".map-fireworks")) {
        return; // one show at a time
    }
    const canvas = el("canvas", "map-fireworks");
    canvas.setAttribute("aria-hidden", "true");
    document.body.appendChild(canvas);
    const ctx = canvas.getContext("2d");
    if (!ctx) {
        canvas.remove();
        return;
    }
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    let width = 0;
    let height = 0;
    const resize = () => {
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = Math.round(width * dpr);
        canvas.height = Math.round(height * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    resize();
    window.addEventListener("resize", resize);

    const rect = anchor ? anchor.getBoundingClientRect() : null;
    const centreX = rect ? rect.left + rect.width / 2 : width / 2;
    const centreY = rect ? rect.top + rect.height / 2 : height / 2;
    const spreadX = Math.min(width * 0.45, 260);
    // Shells burst anywhere from near the top of the screen down to the castle.
    const topY = Math.max(50, height * 0.12);
    const bottomY = Math.max(topY + 80, Math.min(centreY, height * 0.8));
    const small = width < 520;

    const SHOW_MS = 5000;
    const SHELLS = small ? 9 : 14;
    const PARTICLES = small ? 46 : 74;
    const GRAVITY = 140; // px/s^2
    const rockets = [];
    const sparks = [];
    const started = performance.now();
    let launched = 0;
    let last = started;
    let frame = 0;

    const launch = () => {
        const targetX = centreX + (Math.random() * 2 - 1) * spreadX;
        const targetY = topY + Math.random() * (bottomY - topY);
        rockets.push({
            x: targetX + (Math.random() * 2 - 1) * 30,
            fromY: height + 10,
            targetX,
            targetY,
            born: performance.now(),
            duration: 520 + Math.random() * 220,
            hue: Math.floor(Math.random() * 360),
            prevX: 0,
            prevY: 0,
        });
    };

    const burst = (x, y, hue) => {
        const mixed = Math.random() < 0.4;
        for (let i = 0; i < PARTICLES; i++) {
            const angle = (Math.PI * 2 * i) / PARTICLES + Math.random() * 0.2;
            const speed = 70 + Math.random() * 190;
            sparks.push({
                x,
                y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                age: 0,
                life: 0.9 + Math.random() * 0.9,
                hue: mixed ? (hue + (i % 3) * 40) % 360 : hue,
                size: 1.4 + Math.random() * 1.6,
            });
        }
    };

    const stop = () => {
        cancelAnimationFrame(frame);
        window.removeEventListener("resize", resize);
        canvas.remove();
    };

    const tick = (now) => {
        const dt = Math.min((now - last) / 1000, 0.05);
        last = now;
        if (anchor && !anchor.isConnected) {
            stop(); // the learner left the map
            return;
        }
        // Fade the previous frame instead of clearing it: that leaves trails.
        ctx.globalCompositeOperation = "destination-out";
        ctx.fillStyle = "rgba(0, 0, 0, 0.22)";
        ctx.fillRect(0, 0, width, height);
        ctx.globalCompositeOperation = "lighter";

        const elapsed = now - started;
        while (launched < SHELLS && elapsed >= launched * (SHOW_MS - 1200) / SHELLS) {
            launch();
            launched++;
        }
        for (let i = rockets.length - 1; i >= 0; i--) {
            const rocket = rockets[i];
            const t = Math.min((now - rocket.born) / rocket.duration, 1);
            const eased = 1 - (1 - t) * (1 - t);
            const x = rocket.x + (rocket.targetX - rocket.x) * eased;
            const y = rocket.fromY + (rocket.targetY - rocket.fromY) * eased;
            ctx.fillStyle = `hsl(${rocket.hue} 100% 80%)`;
            ctx.fillRect(x - 1, y - 1, 2, 5);
            if (t >= 1) {
                burst(rocket.targetX, rocket.targetY, rocket.hue);
                rockets.splice(i, 1);
            }
        }
        for (let i = sparks.length - 1; i >= 0; i--) {
            const spark = sparks[i];
            spark.age += dt;
            if (spark.age >= spark.life) {
                sparks.splice(i, 1);
                continue;
            }
            const drag = Math.pow(0.55, dt * 3);
            spark.vx *= drag;
            spark.vy = spark.vy * drag + GRAVITY * dt;
            spark.x += spark.vx * dt;
            spark.y += spark.vy * dt;
            const alpha = 1 - spark.age / spark.life;
            ctx.fillStyle = `hsl(${spark.hue} 100% ${55 + alpha * 20}% / ${alpha.toFixed(2)})`;
            ctx.beginPath();
            ctx.arc(spark.x, spark.y, spark.size, 0, Math.PI * 2);
            ctx.fill();
        }
        if (launched >= SHELLS && !rockets.length && !sparks.length) {
            stop();
            return;
        }
        frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
}

// ============================================================================
// 4c. Cheat codes (to try the finale without finishing the course)
// ============================================================================

/**
 * `?cheat=fireworks` in the page address: the map is drawn as if the
 * whole course were done and the finale plays, every time. Nothing is
 * stored. Handy on a phone, where there is no console.
 */
function cheatRequested() {
    try {
        return new URLSearchParams(window.location.search).get("cheat") === "fireworks";
    } catch (err) {
        return false;
    }
}

const KONAMI = ["ArrowUp", "ArrowUp", "ArrowDown", "ArrowDown", "ArrowLeft", "ArrowRight", "ArrowLeft", "ArrowRight", "b", "a"];
let konamiProgress = 0;

/**
 * The Konami code (↑ ↑ ↓ ↓ ← → ← → B A) on a keyboard sets off the
 * fireworks over the map on screen. Display only: nothing is stored.
 */
function onKonamiKey(event) {
    if (event.target && /^(input|textarea|select)$/i.test(event.target.tagName)) {
        return;
    }
    const key = event.key.length === 1 ? event.key.toLowerCase() : event.key;
    konamiProgress = key === KONAMI[konamiProgress] ? konamiProgress + 1 : (key === KONAMI[0] ? 1 : 0);
    if (konamiProgress === KONAMI.length) {
        konamiProgress = 0;
        const section = document.getElementById("adventure-map");
        if (section && !prefersReducedMotion()) {
            const finalNode = section.querySelector(".map-node--final");
            launchFireworks(finalNode);
        }
    }
}
document.addEventListener("keydown", onKonamiKey);

/** Move an already-built scene to `state`: nodes, path, fog. */
function applyState(section, steps, state) {
    section.querySelectorAll(".map-node").forEach((node) => {
        const index = Number(node.dataset.index);
        if (updateNode(node, steps[index], state.steps[index])) {
            node.classList.add("is-new");
            setTimeout(() => node.classList.remove("is-new"), 900);
        }
    });
    section.querySelectorAll(".route-segment").forEach((segment) => {
        segment.classList.toggle("is-discovered", state.steps[Number(segment.dataset.segment) + 1].discovered);
    });
    section.querySelectorAll(".fog-zone").forEach((zone) => {
        zone.classList.toggle("is-revealed", state.steps[Number(zone.dataset.index)].discovered);
    });
}

/** Build the scene: background, scenery, route, fog, nodes, fox. */
function buildScene(steps, state, config) {
    const section = el("section", "adventure-map");
    section.id = "adventure-map";
    section.dataset.steps = String(steps.length);
    section.setAttribute("aria-label", uiLabel("map_title", "Adventure map"));

    // A course may ship its own artwork (config.background, a path under
    // the site root). Without it, the CSS placeholder landscape is kept.
    const hasArtwork = Boolean(config && typeof config.background === "string" && config.background);
    const background = el("div", "map-background");
    if (hasArtwork) {
        background.style.backgroundImage = `url("${encodeURI(config.background)}")`;
    }
    section.appendChild(background);

    // The artwork already paints its own scenery (forests, falls, peaks):
    // the generic decorations are only drawn over the placeholder landscape.
    if (!hasArtwork) {
        const decorations = el("div", "map-decorations");
        decorations.setAttribute("aria-hidden", "true");
        MAP_DECORATIONS.forEach((item) => {
            const deco = el("span", "map-decoration", item.icon);
            deco.style.left = `${item.x}%`;
            deco.style.top = `${item.y}%`;
            deco.style.fontSize = `${item.size}rem`;
            decorations.appendChild(deco);
        });
        section.appendChild(decorations);
    }

    section.appendChild(buildRoute(steps, state));
    section.appendChild(buildFog(steps, state));

    const nodes = el("div", "map-nodes");
    steps.forEach((step, index) => nodes.appendChild(buildNode(step, index, state.steps[index])));
    section.appendChild(nodes);

    const fox = el("div", "map-fox", "🦊");
    fox.id = "map-fox";
    fox.setAttribute("aria-hidden", "true");
    section.appendChild(fox);

    return section;
}

/**
 * The path: the whole route faintly, and one segment per step pair
 * that lights up once its destination is discovered. Drawn in a
 * 1000x1000 box stretched over the map, so percent coordinates and
 * the SVG always line up.
 */
function buildRoute(steps, state) {
    const svg = document.createElementNS(SVG_NS, "svg");
    svg.setAttribute("class", "map-route");
    svg.setAttribute("viewBox", "0 0 1000 1000");
    svg.setAttribute("preserveAspectRatio", "none");
    svg.setAttribute("aria-hidden", "true");

    const segments = splineSegments(steps.map((step) => [step.x * 10, step.y * 10]));
    segments.forEach((d) => svg.appendChild(svgPath("route route--hidden", d)));
    segments.forEach((d, index) => {
        const segment = svgPath("route route--visible route-segment", d);
        segment.dataset.segment = String(index);
        segment.classList.toggle("is-discovered", state.steps[index + 1].discovered);
        svg.appendChild(segment);
    });
    return svg;
}

/** One fog patch per step after the first; clear once it is discovered. */
function buildFog(steps, state) {
    const fog = el("div", "map-fog");
    fog.setAttribute("aria-hidden", "true");
    steps.forEach((step, index) => {
        if (index === 0) {
            return;
        }
        const zone = el("div", "fog-zone");
        zone.dataset.index = String(index);
        zone.style.left = `${step.x}%`;
        zone.style.top = `${step.y}%`;
        zone.classList.toggle("is-revealed", state.steps[index].discovered);
        fog.appendChild(zone);
    });
    return fog;
}

function buildNode(step, index, nodeState) {
    const node = el("button", `map-node map-node--${step.type}`);
    node.type = "button";
    node.dataset.index = String(index);
    node.style.left = `${step.x}%`;
    node.style.top = `${step.y}%`;
    node.appendChild(el("span", "map-node__icon", step.icon));
    node.appendChild(el("span", "map-node__label", step.title));
    updateNode(node, step, nodeState);
    return node;
}

/**
 * Set a node's state class, accessible name and score badge.
 * @returns {boolean} true if its state class changed.
 */
function updateNode(node, step, nodeState) {
    const stateClass = nodeStateClass(nodeState);
    const changed = !node.classList.contains(stateClass);
    ["is-validated", "is-current", "is-in-progress", "is-discovered", "is-future"].forEach((name) => {
        node.classList.toggle(name, name === stateClass);
    });

    const parts = [step.title];
    if (nodeState.score !== null) {
        parts.push(`${nodeState.score}%`);
    }
    parts.push(nodeStateText(nodeState));
    node.setAttribute("aria-label", parts.join(", "));

    let badge = node.querySelector(".map-node__score");
    if (nodeState.score !== null) {
        if (!badge) {
            badge = el("span", "map-node__score");
            node.appendChild(badge);
        }
        badge.textContent = `${nodeState.score}%`;
    } else if (badge) {
        badge.remove();
    }
    return changed;
}

// ============================================================================
// 5. Fox
// ============================================================================

/**
 * Put the fox on the map. With nothing opened yet it starts off the
 * top edge, next to the first step, and walks in.
 */
function placeFox(section, steps) {
    const fox = section.querySelector("#map-fox");
    const index = foxStepIndex(steps);
    const targetIndex = index >= 0 ? index : 0;
    const [targetX, targetY] = foxSpot(steps[targetIndex]);
    fox.dataset.step = String(targetIndex);

    // First position: set without a transition, otherwise the fox would
    // glide in from the stylesheet's default corner on every page load.
    placeInstantly(fox, targetX, index >= 0 ? targetY : -12);
    if (index < 0) {
        // Nothing opened yet: walk in from above the map.
        requestAnimationFrame(() => requestAnimationFrame(() => setFoxAt(fox, targetX, targetY)));
    }
}

/** Move the fox with no transition (the next move animates again). */
function placeInstantly(fox, x, y) {
    fox.style.transition = "none";
    setFoxAt(fox, x, y);
    fox.getBoundingClientRect(); // flush, so "none" applies to this move only
    fox.style.transition = "";
}

/**
 * Where the fox stands for a step: beside the icon, on the side the
 * path comes from / goes to (towards the middle of the map), and level
 * with the icon so it never hides the label underneath.
 */
function foxSpot(step) {
    const side = step.x < 50 ? 1 : -1;
    return [step.x + side * 9, step.y - 2];
}

function setFoxAt(fox, x, y) {
    fox.style.setProperty("--fox-x", `${x}%`);
    fox.style.setProperty("--fox-y", `${y}%`);
}

const FOX_WALK_MAX_MS = 1200;
const FOX_HOP_MIN_MS = 120;
const FOX_HOP_MAX_MS = 600;

/**
 * Walk the fox to a step, passing through every step in between (it
 * follows the path, it does not cut across the map). The whole walk
 * lasts FOX_WALK_MAX_MS at most, however far the step is.
 *
 * A newer walk supersedes an older one: the fox simply turns round from
 * where it is. With reduced motion it jumps.
 *
 * @returns {Promise<boolean>} true if the fox arrived, false if this
 *     walk was superseded on the way.
 */
async function walkFox(section, steps, toIndex) {
    const fox = section.querySelector("#map-fox");
    const from = Number(fox.dataset.step);
    const walk = Symbol("walk");
    fox._walk = walk;

    const last = steps[toIndex];
    if (!Number.isInteger(from) || from === toIndex || prefersReducedMotion()) {
        const [x, y] = foxSpot(last);
        setFoxAt(fox, x, y);
        fox.dataset.step = String(toIndex);
        fox.classList.remove("is-walking");
        return true;
    }

    const direction = toIndex > from ? 1 : -1;
    const hops = Math.abs(toIndex - from);
    const hopMs = Math.min(FOX_HOP_MAX_MS, Math.max(FOX_HOP_MIN_MS, FOX_WALK_MAX_MS / hops));
    fox.style.setProperty("--fox-duration", `${hopMs}ms`);
    fox.classList.add("is-walking");

    for (let index = from + direction; ; index += direction) {
        const [x, y] = foxSpot(steps[index]);
        fox.dataset.step = String(index);
        setFoxAt(fox, x, y);
        await new Promise((resolve) => setTimeout(resolve, hopMs));
        if (fox._walk !== walk) {
            return false;
        }
        if (index === toIndex) {
            break;
        }
    }
    fox.classList.remove("is-walking");
    return true;
}

const FOX_DIVE_MS = 450;

/**
 * The fox jumps into a sheet row of the bubble (shrinking as it goes),
 * then `done` runs -- that is what opens the sheet. A guard keeps a
 * double tap from starting it twice. Never used with reduced motion
 * (the caller opens the sheet at once).
 */
function diveFox(section, row, done) {
    const fox = section.querySelector("#map-fox");
    if (!fox || fox._diving) {
        return;
    }
    fox._diving = true;
    fox._walk = Symbol("dive"); // a walk in progress must not undo this
    fox.classList.remove("is-walking", "is-celebrating");

    const box = section.getBoundingClientRect();
    const target = row.getBoundingClientRect();
    // The row's left end, where its marker is, not its middle.
    const x = ((target.left + 22 - box.left) / box.width) * 100;
    const y = ((target.top + target.height / 2 - box.top) / box.height) * 100;

    fox.style.setProperty("--fox-duration", `${FOX_DIVE_MS}ms`);
    fox.classList.add("is-diving");
    setFoxAt(fox, x, y);
    setTimeout(() => row.classList.add("is-entered"), FOX_DIVE_MS * 0.7);
    setTimeout(() => {
        fox._diving = false;
        if (section.isConnected) {
            done();
        }
    }, FOX_DIVE_MS + 40);
}

// ============================================================================
// 6. Step bubble
// ============================================================================

/** @returns {{id: string, title: string}|null} A sheet of the course, by id. */
function findSheet(sheetId) {
    for (const group of (typeof DATA !== "undefined" && DATA && DATA.groups) || []) {
        const sheet = group.sheets.find((candidate) => candidate.id === sheetId);
        if (sheet) {
            return sheet;
        }
    }
    return null;
}

/**
 * The bubble that opens under (or over) a step when it is clicked: the
 * step's score and its sheets, one tap each. It lives inside the map,
 * anchored to the step, so the rest of the map stays in view; it closes
 * on a click anywhere else on the map, Escape, its x, or a second click
 * on the same step. No listener is ever put on `document`.
 */
function buildBubble(section) {
    const element = el("div", "map-bubble");
    element.hidden = true;
    element.setAttribute("role", "dialog");
    element.setAttribute("aria-labelledby", "map-bubble-title");

    const head = el("div", "map-bubble__head");
    const heading = el("div", "map-bubble__heading");
    const title = el("h2", "map-bubble__title");
    title.id = "map-bubble-title";
    // One short line under the title ("not discovered yet", or the
    // castle's message). The rows are enough to say it can be explored.
    const note = el("p", "map-bubble__note");
    heading.append(title, note);
    const score = el("span", "map-bubble__score");
    const close = el("button", "map-bubble__close", "×");
    close.type = "button";
    close.setAttribute("aria-label", uiLabel("map_close", "Close"));
    head.append(heading, score, close);
    const list = el("ul", "map-bubble__list");
    element.append(head, list);
    section.appendChild(element);

    let openIndex = -1;
    let opener = null;

    function hide(restoreFocus) {
        element.hidden = true;
        openIndex = -1;
        if (restoreFocus && opener) {
            opener.focus();
        }
        opener = null;
    }
    close.addEventListener("click", () => hide(true));

    /** One link per sheet; the one to resume is marked. */
    function fillRows(step) {
        list.textContent = "";
        const lastId = getLastSheetId();
        step.sheets.forEach((sheetId) => {
            const sheet = findSheet(sheetId);
            if (!sheet) {
                return;
            }
            const row = el("a", "map-bubble__row");
            row.href = `#/sheet/${encodeURIComponent(sheetId)}`;
            row.appendChild(el("span", "map-bubble__row-title", splitTitle(sheet.title).title));
            if (sheetId === lastId) {
                row.setAttribute("aria-current", "true");
                row.prepend(el("span", "map-sr-only", uiLabel("map_continue", "Continue") + ": "));
            }
            const progress = getSheetProgress(sheetId);
            if (progress && progress.last) {
                row.appendChild(el("span", "map-bubble__row-score", `${progress.last.score}/${progress.last.total}`));
            }
            row.addEventListener("click", (event) => {
                // Plain left click only: ctrl/middle click keep their
                // usual meaning, and reduced motion opens at once.
                if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || prefersReducedMotion()) {
                    return;
                }
                event.preventDefault();
                diveFox(section, row, () => {
                    window.location.hash = row.getAttribute("href");
                });
            });
            const item = el("li");
            item.appendChild(row);
            list.appendChild(item);
        });
    }

    /** Anchor under the step, or over it when there is more room there. */
    function place(node) {
        const box = section.getBoundingClientRect();
        const anchor = node.getBoundingClientRect();
        const margin = 6;
        const gap = 8;

        element.style.maxHeight = "";
        const width = element.offsetWidth;
        const height = element.offsetHeight;
        const centre = anchor.left + anchor.width / 2 - box.left;
        const left = Math.min(Math.max(centre - width / 2, margin), box.width - width - margin);

        const roomBelow = box.bottom - anchor.bottom - gap - margin;
        const roomAbove = anchor.top - box.top - gap - margin;
        const below = height <= roomBelow || roomBelow >= roomAbove;
        const room = Math.max(120, below ? roomBelow : roomAbove);
        const shown = Math.min(height, room);

        element.style.maxHeight = `${Math.floor(room)}px`;
        element.style.left = `${Math.round(left)}px`;
        element.style.top = `${Math.round(below ? anchor.bottom - box.top + gap : anchor.top - box.top - gap - shown)}px`;
        element.style.setProperty("--arrow-x", `${Math.round(Math.min(Math.max(centre - left, 18), width - 18))}px`);
        element.classList.toggle("map-bubble--above", !below);
    }

    function open(index, node) {
        const step = MAP_DATA.steps[index];
        const state = deriveMapState(MAP_DATA.steps, MAP_DATA.config).steps[index];

        title.textContent = step.title;
        score.textContent = state.score !== null ? `${state.score}%` : "";
        if (step.type === "final" && step.sheets.length === 0) {
            note.textContent = uiLabel("map_castle_soon", "The final exam is coming soon.");
        } else {
            note.textContent = state.discovered ? "" : uiLabel("map_not_discovered", "not discovered yet");
        }
        fillRows(step);

        opener = node;
        openIndex = index;
        element.hidden = false;
        place(node);
        const target = list.querySelector("[aria-current]") || list.querySelector("a") || close;
        target.focus({ preventScroll: true });
    }

    return {
        element,
        open,
        close: hide,
        get index() { return openIndex; },
        get isOpen() { return openIndex >= 0; },
    };
}

// ============================================================================
// 7. Direct access to resources outside the path
// ============================================================================

/**
 * Links to the categories that are not part of the path (dialogues,
 * vocabulary, annexes...): they scroll to, and open, that section of
 * the sheet list below the map.
 * @returns {HTMLElement|null} null if the course has no such category.
 */
function buildResourcesNav(resources) {
    if (!resources.length) {
        return null;
    }
    const nav = el("nav", "direct-access");
    nav.setAttribute("aria-label", uiLabel("map_resources", "Resources"));
    const list = el("ul", "direct-access-list");
    resources.forEach((resource) => {
        const item = el("li");
        const link = el("a", "direct-access-link", resource.title);
        link.href = "#/";
        link.addEventListener("click", (event) => {
            event.preventDefault();
            const section = document.querySelector(`.index-section[data-category="${resource.id}"]`);
            if (section) {
                const outer = section.closest("details.all-sheets");
                if (outer) {
                    outer.open = true;
                }
                section.open = true;
                section.scrollIntoView({ behavior: "smooth", block: "start" });
            }
        });
        item.appendChild(link);
        list.appendChild(item);
    });
    nav.appendChild(list);
    return nav;
}

window.renderMap = renderMap;
})();
